	/// <return>The visitor result.</return>
	Result VisitIdentifier([NotNull] GlslParser.IdentifierContext context);
	/// <summary>
	/// Visit a parse tree produced by the <c>literalExpr</c>
	/// labeled alternative in <see cref="GlslParser.primaryExpression"/>.
