	Result VisitLiteralExpr([NotNull] GlslParser.LiteralExprContext context);
	/// <summary>
	/// Visit a parse tree produced by the <c>parenExpr</c>
	/// labeled alternative in <see cref="GlslParser.primaryExpression"/>.
	/// </summary>
	/// <param name="context">The parse tree.</param>
	/// <return>The visitor result.</return>
	Result VisitParenExpr([NotNull] GlslParser.ParenExprContext context);
	/// <summary>
	/// Visit a parse tree produced by <see cref="GlslParser.literal"/>.
	/// </summary>
	/// <param name="context">The parse tree.</param>
	/// <return>The visitor result.</return>
	Result VisitLiteral([NotNull] GlslParser.LiteralContext context);
}
